// These phase strings are part of the dashboard's JSON interface.
static const char* phaseName(UpdatePhase phase) {
  switch (phase) {
    case Preparing: return "preparing";
    case QueuedUpdate: return "queued";
    case Downloading: return "downloading";
    case Verifying: return "verifying";
    case Rebooting: return "rebooting";
    case Complete: return "complete";
    case Failed: return "error";
    default: return "idle";
  }
}

// Sample actual output, bounded independently of the configured strip size.
uint16_t InterComms::capturePixels(uint8_t* pixels) {
  size_t total = strip.getLengthTotal();
  uint16_t count = std::min(total, LIVE_LED_LIMIT);
  for (size_t i = 0; i < count; i++) {
    uint32_t color = strip.getPixelColor(i * total / count);
    pixels[i * 3] = qadd8(W(color), R(color));
    pixels[i * 3 + 1] = qadd8(W(color), G(color));
    pixels[i * 3 + 2] = qadd8(W(color), B(color));
  }
  return count;
}

// Return cached remote pixels through the gateway; only authenticated requests refresh them.
void InterComms::live(JsonObject request, JsonObject result) {
  uint8_t target[6];
  if (!fromHex(request["target"], target, sizeof(target))) { result["error"] = "Invalid live device"; return; }
  JsonArray leds = result.createNestedArray("leds");
  uint8_t pixels[LIVE_LED_LIMIT * 3];
  uint16_t count = 0;
  if (equal(target, _id, sizeof(target))) count = capturePixels(pixels);
  else {
    int index = peerFor(target, false);
    if (index < 0 || !_peers[index].live(millis())) { result["error"] = "Live device is offline"; return; }
    Member& member = _members[index];
    if (!member.liveRelay) { result["error"] = "Update this device to relay its live output"; return; }
    if (elapsed(millis(), member.liveRequested, 150)) {
      if (sendPeer(index, LiveRequest, nullptr, 0)) member.liveRequested = millis();
    }
    if (!elapsed(millis(), member.liveAt, 1000)) {
      count = member.liveCount; memcpy(pixels, member.livePixels, count * 3);
    }
  }
  for (size_t i = 0; i < count; i++) {
    char color[7]; snprintf(color, sizeof(color), "%02x%02x%02x", pixels[i * 3], pixels[i * 3 + 1], pixels[i * 3 + 2]);
    leds.add(String(color));
  }
  result["ok"] = true;
}

// Publish only lighting state; presets, playlists, hardware and network settings are not executable state messages.
void InterComms::lighting(JsonObject object) {
  serializeState(object, true, true, true, false);
  object["tb"] = uint32_t(millis() + strip.timebase);
}

// Copy a strict state allowlist before invoking WLED's existing range-clamped JSON parser.
bool InterComms::applyLighting(JsonObject input) {
  if (input.isNull()) return false;
  DynamicJsonDocument safe(8192);
  JsonObject output = safe.to<JsonObject>();
  for (const char* key : {"on", "bri", "transition", "mainseg"}) if (input.containsKey(key)) output[key] = input[key];
  if (input.containsKey("seg")) {
    JsonArray segments = input["seg"];
    if (segments.isNull() || segments.size() > WS2812FX::getMaxSegments()) return false;
    JsonArray result = output.createNestedArray("seg");
    for (JsonObject segment : segments) {
      if (segment.isNull()) return false;
      JsonObject target = result.createNestedObject();
      for (const char* key : {"id", "start", "stop", "grp", "spc", "of", "on", "bri", "col", "fx", "sx", "ix", "pal", "sel", "rev", "mi", "c1", "c2", "c3", "o1", "o2", "o3", "si", "m12", "set"}) {
        if (segment.containsKey(key)) target[key] = segment[key];
      }
      if (target.containsKey("start")) target["start"] = constrain(target["start"].as<int>(), 0, int(strip.getLengthTotal()));
      if (target.containsKey("stop")) target["stop"] = constrain(target["stop"].as<int>(), 0, int(strip.getLengthTotal()));
    }
  }
  if (safe.overflowed()) return false;
  if (input["tb"].is<uint32_t>()) strip.timebase = input["tb"].as<uint32_t>() - millis();
  _applying = true;
  deserializeState(output, CALL_MODE_NO_NOTIFY);
  _applying = false;
  return true;
}

// Persist only explicit project settings, never arbitrary cfg.json objects or GPIO fields.
bool InterComms::applySettings(JsonObject settings) {
  if (settings.isNull()) return false;
  for (JsonPair entry : settings) {
    const char* key = entry.key().c_str();
    if (strcmp(key, "name") && strcmp(key, "sync") && strcmp(key, "bootOn") && strcmp(key, "bootBrightness") && strcmp(key, "transitionMs")) return false;
  }
  if (settings.containsKey("name") && (!settings["name"].is<const char*>() || strnlen(settings["name"], sizeof(serverDescription)) >= sizeof(serverDescription))) return false;
  if (settings.containsKey("sync") && !settings["sync"].is<bool>()) return false;
  if (settings.containsKey("bootOn") && !settings["bootOn"].is<bool>()) return false;
  if (settings.containsKey("bootBrightness") && (!settings["bootBrightness"].is<unsigned>() || settings["bootBrightness"].as<unsigned>() > 255)) return false;
  if (settings.containsKey("transitionMs") && (!settings["transitionMs"].is<unsigned>() || settings["transitionMs"].as<unsigned>() > 60000)) return false;
  if (settings.containsKey("name")) strlcpy(serverDescription, settings["name"], sizeof(serverDescription));
  if (settings.containsKey("sync") && _sync != settings["sync"].as<bool>()) {
    _sync = settings["sync"];
    // Rejoining followers adopt the master's next snapshot instead of publishing stale local edits.
    _changed.store(false);
    _dirty = _sync && master();
  }
  if (settings.containsKey("bootOn")) turnOnAtBoot = settings["bootOn"];
  if (settings.containsKey("bootBrightness")) briS = settings["bootBrightness"];
  if (settings.containsKey("transitionMs")) transitionDelayDefault = settings["transitionMs"];
  configNeedsWrite = true;
  return true;
}

// Dispatch the same bounded command allowlist for local administration and peer commands.
bool InterComms::command(const char* op, JsonObject body, int source) {
  _commandError[0] = 0;
  if (!op) return false;
  if (!strcmp(op, "lighting")) {
    if (body.containsKey("independent") && !body["independent"].is<bool>()) return false;
    if (_firmware.active || !applyLighting(body)) return false;
    // Explicit dashboard edits opt the target out of periodic group snapshots.
    if ((body["independent"] | false) && _sync) {
      _sync = false; _dirty = false; _changed.store(false); configNeedsWrite = true;
    }
    return true;
  }
  if (!strcmp(op, "settings")) return applySettings(body);
  if (!strcmp(op, "firmware")) return beginFirmware(body, source);
  return false;
}

// Track one reliable command per peer; responses expose acknowledgement or timeout to the dashboard.
bool InterComms::queueCommand(int peer, const char* op, JsonObject body) {
  Member& member = _members[peer];
  if (member.commandLength || !++_commandId) return false;
  DynamicJsonDocument document(2048);
  document["op"] = op; document["id"] = _commandId; document["body"] = body;
  size_t length = measureJson(document);
  if (document.overflowed() || length >= sizeof(member.command)) return false;
  member.commandLength = serializeJson(document, member.command, sizeof(member.command));
  member.commandId = _commandId; member.attempts = 0; member.commandSent = millis() - COMMAND_RETRY_MS;
  strlcpy(member.result, "Queued", sizeof(member.result));
  return true;
}

// Retry each queued peer command within its existing attempt/time limits, preserving update failure reporting.
void InterComms::serviceCommands(uint32_t now) {
  for (size_t i = 0; i < MAX_PEERS; i++) {
    Member& member = _members[i];
    if (!master() && !member.updateTracked) continue;
    if (!member.commandLength || !elapsed(now, member.commandSent, COMMAND_RETRY_MS)) continue;
    if (!_peers[i].live(now) || member.attempts >= COMMAND_ATTEMPTS) {
      member.commandLength = 0; strlcpy(member.result, "No acknowledgement", sizeof(member.result)); if (member.updateTracked) member.updatePhase = Failed; continue;
    }
    sendPeer(i, Command, reinterpret_cast<const uint8_t*>(member.command), member.commandLength);
    member.commandSent = now; member.attempts++;
  }
}

