// Dashboard commands are public; device-to-device commands still require group authentication.
void InterComms::admin(JsonObject input, JsonObject result) {
  const char* op = input["op"] | "";
  if (!strcmp(op, "status")) { status(result); return; }
  if (!strcmp(op, "live")) { live(input, result); return; }
  if (!strcmp(op, "effects")) {
    result["ok"] = true;
    JsonArray effects = result.createNestedArray("effects");
    for (size_t i = 0; i < strip.getModeCount(); i++) {
      const char* name = strip.getModeData(i);
      char label[48]; size_t j = 0;
      while (j + 1 < sizeof(label) && name[j] && name[j] != '@') { label[j] = name[j]; j++; }
      label[j] = 0; effects.add(label);
    }
    return;
  }
  JsonObject body = input["body"];
  if (!strcmp(op, "wifi")) {
    const char* ssid = body["ssid"], *password = body["password"];
    if (!ssid || !password || !strnlen(ssid, 33) || strnlen(ssid, 33) > 32 || strnlen(password, 65) > 64 || !input["confirm"].as<bool>()) { result["error"] = "Invalid Wi-Fi setup"; return; }
    multiWiFi.clear(); multiWiFi.emplace_back(ssid, password);
    configNeedsWrite = true;
    result["ok"] = true; result["message"] = "Wi-Fi saved; reboot to connect";
    return;
  }
  if (!strcmp(op, "reboot")) { result["ok"] = true; doReboot = true; return; }
  if (!master()) { result["error"] = "Open the elected master dashboard; election takes five seconds"; return; }
  if (!strcmp(op, "prepareCurrent")) {
    result["ok"] = prepareCurrent(); if (_commandError[0]) result["error"] = _commandError; return;
  }
  if (!strncmp(op, "upload", 6)) {
    result["ok"] = stage(op, body);
    if (_uploadError[0]) result["error"] = _uploadError;
    return;
  }
  if (!strcmp(op, "rollout") || !strcmp(op, "installLocal")) {
    distributeFirmware(op, input["target"] | "all", result);
    return;
  }
  if (strcmp(op, "settings") && strcmp(op, "lighting")) { result["error"] = "Unknown command"; return; }
  dispatchToTargets(op, body, input["target"] | "all", result);
}

// Apply locally and queue remote recipients; accepted commands can still be awaiting a peer's ACK.
void InterComms::dispatchToTargets(const char* op, JsonObject body, const char* target, JsonObject result) {
  bool all = !strcmp(target, "all");
  uint8_t identifier[6];
  if (!all && !fromHex(target, identifier, 6)) { result["error"] = "Invalid device ID"; return; }
  unsigned accepted = 0, failed = 0;
  if (all || equal(identifier, _id, 6)) { if (command(op, body, -1)) accepted++; else failed++; }
  for (size_t i = 0; i < MAX_PEERS; i++) {
    if (_peers[i].live(millis()) && (all || equal(identifier, _peers[i].id, 6))) {
      if (queueCommand(i, op, body)) accepted++; else failed++;
    }
  }
  if (all && !strcmp(op, "lighting")) _dirty = true;
  result["ok"] = accepted > 0 && failed == 0; result["accepted"] = accepted; result["failed"] = failed;
}

// Recover after dropped packets with periodic snapshots; effect clocks share the leader's timebase.
void InterComms::synchronize() {
  if (!settled() || !_sync || _firmware.active) return;
  if (_changed.exchange(false)) { _dirty = true; _lastLocal = millis(); }
  bool periodic = master() && elapsed(millis(), _lastState, HEARTBEAT_MS);
  if (!periodic && (!_dirty || !elapsed(millis(), _lastLocal, 60))) return;
  DynamicJsonDocument document(8192);
  lighting(document.to<JsonObject>());
  if (document.overflowed() || measureJson(document) > MAX_PAYLOAD) { _dirty = false; return; }
  if (master()) {
    // Resume at the first unsent peer if a large snapshot exhausts the bounded transport queue.
    for (size_t step = 0; step < MAX_PEERS; step++) {
      size_t i = (_stateCursor + step) % MAX_PEERS;
      if (_peers[i].live(millis()) && _members[i].sync && !sendJson(i, State, document)) { _stateCursor = i; break; }
    }
  } else sendJson(_leader, Proposal, document);
  _dirty = false; _lastState = millis();
}

